import React from 'react';
import { Link } from 'react-router-dom';

const Login = () => {
  return (
    <div className="container">
      <h1>Login</h1>
      <p>Please login to continue</p>
      <Link to="/register">Don't have an account? Register</Link>
    </div>
  );
};

export default Login;
